console.log("Strategy: " + DATA.strategy);
console.log("Oracle: " + DATA.oracle);
console.log("Coverage goal: " + DATA.goal);
var generated = [];
inputs.forEach(function (inp, i) {
  // deterministic expansion: boundary variants of each seed input
  var variants = [inp, inp + "_empty", inp + "_max", "not_" + inp];
  variants.forEach(function (v, j) {
    var verdict = (v.length % 3 === 0) ? "FAIL(expected)" : "pass";
    generated.push({ input: v, verdict: verdict });
  });
});
generated.forEach(function (g, i) { console.log("  test " + (i + 1) + ": input=" + g.input + " -> " + g.verdict); });
console.log("RESULT: " + generated.length + " tests generated from " + inputs.length + " seeds.");

